import { useEffect, useMemo, useState } from 'react';
import { FlatList, Modal, Pressable, StyleSheet, Text, TextInput, useWindowDimensions, View } from 'react-native';
import { initializeTakaiLaborNotebook } from '../../data';
import { tokens } from '../../theme/tokens';
import { AppShell, ConfirmActionSheet, DatePickerField, FeedbackToast, FieldCard, FormFeedback, LedgerListCard, LedgerListRow, LedgerRowText, LedgerTrailing, MultiSearchPickerSheet, PickerField, PrimaryButton, ScreenSkeleton, SearchPickerSheet, SectionHeader, StatusChip, TopBar, type BottomTabKey } from '../../ui';
import type { LaborV2Adapter } from './previewV2Adapter';
import type { LaborV2OpenContractBatch, LaborV2PersonDetail, LaborV2ReadModel, LaborV2TaskDetail, LaborV2WorkListFilters, LaborWorker, LaborWorkerAdvance } from './types';
import { selectLaborWebProofScenario, selectLaborWebProofScreen, selectLaborWebProofVisual } from './webProofVisual';
import { LaborRecordGroupEditor } from './LaborRecordGroupEditor';

type Tab = 'today' | 'work' | 'record' | 'payment' | 'people';
type Kind = 'daily' | 'hourly' | 'contract';
export type Ready = { adapter: LaborV2Adapter; model: LaborV2ReadModel; workers: LaborWorker[]; openContracts: LaborV2OpenContractBatch[]; advances: LaborWorkerAdvance[]; date: string };
const tabTitle: Record<Tab, string> = { today: 'วันนี้', work: 'งาน', record: 'บันทึกงาน', payment: 'จ่ายเงิน', people: 'คน' };
const todayKey = () => new Date().toISOString().slice(0, 10);
const baht = (satang: number) => `${new Intl.NumberFormat('th-TH', { maximumFractionDigits: 0 }).format(satang / 100)} บาท`;
const personName = (workers: LaborWorker[], id: string | null) => workers.find((item) => item.id === id)?.displayName ?? 'ประวัติเดิม';

export function LaborMvpApp() {
  const visual = selectLaborWebProofVisual(); const [tab, setTab] = useState<Tab>(() => selectLaborWebProofScreen() ?? 'today'); const [ready, setReady] = useState<Ready | null>(null); const [message, setMessage] = useState<string | null>(null); const [retry, setRetry] = useState(0); const [paymentPersonId, setPaymentPersonId] = useState<string | null>(null);
  const load = async (adapter?: LaborV2Adapter) => { const current = adapter ?? ready?.adapter; if (!current) return; const [model, workers, openContracts, advances] = await Promise.all([current.getReadModel(), current.workers.list(true), current.contracts.listOpen(), current.personFinance.listAdvances()]); setReady({ adapter: current, model, workers, openContracts, advances, date: todayKey() }); };
  useEffect(() => { let alive = true; void initializeTakaiLaborNotebook().then(async (adapter) => { const [model, workers, openContracts, advances] = await Promise.all([adapter.getReadModel(), adapter.workers.list(true), adapter.contracts.listOpen(), adapter.personFinance.listAdvances()]); const fixtureDate = [...model.tasks].map((item) => item.workDate).sort().at(-1); if (alive) setReady({ adapter, model, workers, openContracts, advances, date: adapter.mode === 'proof' && fixtureDate ? fixtureDate : todayKey() }); }).catch(() => alive && setMessage('เปิดสมุดงานไม่สำเร็จ')); return () => { alive = false; }; }, [retry]);
  if (!ready) return <ScreenSkeleton lines={4} />;
  const props = { ready, refresh: () => load(), notify: setMessage };
  return <View style={styles.root}><AppShell activeTab={tab as BottomTabKey} keyboardAware={tab === 'record' || tab === 'people'} onTabPress={(next) => setTab(next as Tab)} showTabs variant="tabbed" scrollEnabled={tab !== 'work'}>
    <TopBar hideSubtitle title={tabTitle[tab]} variant="default" onInfoPress={() => setMessage('TAKAI · บันทึกงานและค่าแรงแยกกัน')} />{ready.adapter.mode === 'proof' ? <StatusChip label="ข้อมูลทดสอบ V2" variant="offline" /> : null}<Text style={styles.pageTitle}>{tabTitle[tab]}</Text>
    {tab === 'today' ? <TodayScreen {...props} onRecord={() => setTab('record')} onPayment={() => setTab('payment')} onWork={() => setTab('work')} /> : null}
    {tab === 'work' ? <WorkScreen {...props} onRecord={() => setTab('record')} /> : null}
    {tab === 'record' ? <RecordScreen {...props} onPayment={() => setTab('payment')} /> : null}
    {tab === 'payment' ? <PaymentScreen {...props} preferredPersonId={paymentPersonId} /> : null}
    {tab === 'people' ? <PeopleScreen {...props} onPayment={(personId) => { setPaymentPersonId(personId); setTab('payment'); }} /> : null}
  </AppShell><FeedbackToast visible={visual === 'success-toast' || Boolean(message)} message={visual === 'success-toast' ? 'ข้อมูลทดสอบ: บันทึกสำเร็จแล้ว' : message ?? ''} onDismiss={() => setMessage(null)} /></View>;
}

function TodayScreen({ ready, onRecord, onPayment, onWork }: { ready: Ready; onRecord: () => void; onPayment: () => void; onWork: () => void }) {
  const allTasks = ready.model.tasks.filter((item) => item.workDate === ready.date).sort((a, b) => b.id.localeCompare(a.id)); const allUnpaid = ready.model.obligations.filter((item) => item.remainingSatang > 0); const tasks = allTasks.slice(0, 5); const unpaid = allUnpaid.slice(0, 5);
  return <><FieldCard variant="raised"><Text style={styles.eyebrow}>ภาพรวมวันนี้</Text><Text style={styles.title}>งาน {allTasks.length} รายการ</Text><Text style={styles.muted}>ดูงานที่ทำและค่าแรงค้างจ่ายแยกกันอย่างชัดเจน</Text></FieldCard><Summary items={[["งาน", allTasks.length, true], ["ค้างค่าแรง", allUnpaid.reduce((sum, item) => sum + item.remainingSatang, 0), false], ["จ่ายแล้ว", ready.model.obligations.reduce((sum, item) => sum + item.paidSatang, 0), false]]} /><View style={styles.rowHeader}><SectionHeader title="งานที่ทำวันนี้" /><Pressable onPress={onWork}><Text style={styles.route}>ดูงานทั้งหมด</Text></Pressable></View><TaskList tasks={tasks} workers={ready.workers} />{allTasks.length > 5 ? <Text style={styles.caption}>แสดง 5 งานล่าสุดจาก {allTasks.length} งาน</Text> : null}<View style={styles.rowHeader}><SectionHeader title="ค่าแรงค้างจ่าย" /><Pressable onPress={onPayment}><Text style={styles.route}>ดูทั้งหมด</Text></Pressable></View><ObligationList obligations={unpaid} workers={ready.workers} />{allUnpaid.length > 5 ? <Text style={styles.caption}>แสดง 5 รายการล่าสุดจาก {allUnpaid.length} รายการ</Text> : null}<PrimaryButton label="+ บันทึกงานวันนี้" onPress={onRecord} /><PrimaryButton label="ไปที่จ่ายเงิน" variant="secondary" onPress={onPayment} /></>;
}

function WorkScreen({ ready, refresh, notify, onRecord }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; onRecord: () => void }) {
  const { width } = useWindowDimensions(); const calendarCellWidth = Math.floor((width - tokens.spacing.page * 2) / 7); const [month, setMonth] = useState(ready.date.slice(0, 7)); const [selectedDate, setSelectedDate] = useState(ready.date); const [calendar, setCalendar] = useState<Awaited<ReturnType<LaborV2Adapter['getCalendarMonth']>> | null>(null); const [items, setItems] = useState<LaborV2TaskDetail[]>([]); const [cursor, setCursor] = useState<string | null>(null); const [filters, setFilters] = useState<LaborV2WorkListFilters>({}); const [draft, setDraft] = useState<LaborV2WorkListFilters>({}); const [mode, setMode] = useState<'calendar' | 'list' | 'detail'>('calendar'); const [filterVisible, setFilterVisible] = useState(false); const [detail, setDetail] = useState<LaborV2TaskDetail | null>(null);
  const loadMonth = async (next = month) => { const value = await ready.adapter.getCalendarMonth(next); setCalendar(value); const selected = selectedDate.startsWith(next) ? selectedDate : `${next}-01`; setSelectedDate(selected); };
  const loadList = async (nextFilters = filters, nextCursor?: string | null, append = false) => { const result = await ready.adapter.getWorkList(nextFilters, nextCursor ?? undefined, 30); setItems((rows) => append ? [...rows, ...result.items] : result.items); setCursor(result.nextCursor); };
  useEffect(() => { void loadMonth(); }, [month]); useEffect(() => { if (mode === 'list') void loadList(); }, [mode, filters]);
  const previousMonth = () => setMonth((value) => { const date = new Date(`${value}-01T12:00:00`); date.setMonth(date.getMonth() - 1); return date.toISOString().slice(0, 7); }); const nextMonth = () => setMonth((value) => { const date = new Date(`${value}-01T12:00:00`); date.setMonth(date.getMonth() + 1); return date.toISOString().slice(0, 7); });
  const selected = ready.model.tasks.filter((item) => item.workDate === selectedDate); const dayOffset = calendar ? new Date(`${month}-01T12:00:00`).getDay() : 0; const days = calendar?.days ?? []; const openDetail = async (id: string) => { setDetail(await ready.adapter.getTaskDetail(id)); setMode('detail'); };
  if (mode === 'detail' && detail) return <WorkDetailScreen detail={detail} ready={ready} onBack={() => setMode('calendar')} />;
  if (mode === 'list') return <View style={styles.listScreen}><View style={styles.rowHeader}><Text style={styles.title}>งานทั้งหมด</Text><Pressable onPress={() => setMode('calendar')}><Text style={styles.route}>ปฏิทิน</Text></Pressable></View><View style={styles.rowHeader}><Text style={styles.caption}>ค้นจากงานที่บันทึก ไม่ปนรายการจ่ายเงิน</Text><Pressable onPress={() => { setDraft(filters); setFilterVisible(true); }}><Text style={styles.route}>ตัวกรอง</Text></Pressable></View><FlatList data={items} keyExtractor={(item) => item.id} contentContainerStyle={styles.flatList} renderItem={({ item }) => <TaskRow item={item} workers={ready.workers} onPress={() => void openDetail(item.id)} />} ListEmptyComponent={<Empty label="ยังไม่มีงานตามตัวกรอง" />} ListFooterComponent={cursor ? <PrimaryButton label="โหลดงานเพิ่ม" variant="secondary" onPress={() => void loadList(filters, cursor, true)} /> : <LegacyReadContext ready={ready} />} /><WorkFilterSheet visible={filterVisible} value={draft} workers={ready.workers} onChange={setDraft} onClose={() => setFilterVisible(false)} onApply={() => { setFilters(draft); setFilterVisible(false); }} /></View>;
  return <View style={styles.listScreen}><FlatList data={selected.slice(0, 5)} keyExtractor={(item) => item.id} contentContainerStyle={styles.flatList} renderItem={({ item }) => <TaskRow item={{ ...item, wageContexts: [] }} workers={ready.workers} onPress={() => void openDetail(item.id)} />} ListHeaderComponent={<><View style={styles.rowHeader}><Text style={styles.title}>ปฏิทินงาน</Text><Pressable onPress={() => setMode('list')}><Text style={styles.route}>รายการงานทั้งหมด</Text></Pressable></View><View style={styles.monthNav}><Pressable onPress={previousMonth}><Text style={styles.monthButton}>‹</Text></Pressable><Text style={styles.monthLabel}>{new Date(`${month}-01T12:00:00`).toLocaleDateString('th-TH', { month: 'long', year: 'numeric' })}</Text><Pressable onPress={nextMonth}><Text style={styles.monthButton}>›</Text></Pressable></View><View style={styles.week}><Text style={styles.weekday}>อา</Text><Text style={styles.weekday}>จ</Text><Text style={styles.weekday}>อ</Text><Text style={styles.weekday}>พ</Text><Text style={styles.weekday}>พฤ</Text><Text style={styles.weekday}>ศ</Text><Text style={styles.weekday}>ส</Text></View><View style={styles.calendar}>{Array.from({ length: dayOffset }).map((_, index) => <View key={`blank-${index}`} style={[styles.dayBlank, { width: calendarCellWidth }]} />)}{days.map((day) => <Pressable key={day.workDate} onPress={() => setSelectedDate(day.workDate)} style={[styles.dayCell, { width: calendarCellWidth }, selectedDate === day.workDate && styles.daySelected]}><Text style={styles.dayNumber}>{Number(day.workDate.slice(-2))}</Text>{day.taskCount ? <Text style={styles.dayCount}>{day.taskCount}</Text> : null}</Pressable>)}</View><View style={styles.rowHeader}><SectionHeader title={`งานวันที่ ${selectedDate}`} /><Pressable onPress={() => { setFilters({ startDate: selectedDate, endDate: selectedDate }); setMode('list'); }}><Text style={styles.route}>ดูทั้งหมด</Text></Pressable></View></>} ListEmptyComponent={<Empty label="ยังไม่มีงานในวันนี้" />} ListFooterComponent={<><>{selected.length > 5 ? <Text style={styles.caption}>แสดง 5 งานล่าสุด · ดูทั้งหมดเพื่อดูครบ</Text> : null}</>{ready.openContracts.length ? <View style={styles.section}><SectionHeader title="งานเหมาที่ยังไม่สรุปยอด" />{ready.openContracts.map((contract) => <OpenContractCard key={contract.id} contract={contract} ready={ready} refresh={refresh} notify={notify} />)}</View> : null}<PrimaryButton label="+ บันทึกงาน" onPress={onRecord} /></>} /></View>;
}

function TaskRow({ item, workers, onPress }: { item: LaborV2TaskDetail; workers: LaborWorker[]; onPress: () => void }) { return <Pressable onPress={onPress}><LedgerListCard><LedgerListRow><LedgerRowText title={item.title} detail={`${item.workDate} · ${item.assigneePersonIds.map((id) => personName(workers, id)).join(', ')}`} /><LedgerTrailing><Text style={styles.route}>รายละเอียด</Text></LedgerTrailing></LedgerListRow></LedgerListCard></Pressable>; }
function WorkDetailScreen({ detail, ready, onBack }: { detail: LaborV2TaskDetail; ready: Ready; onBack: () => void }) { return <View style={styles.listScreen}><Pressable onPress={onBack}><Text style={styles.route}>‹ กลับไปงาน</Text></Pressable><FieldCard variant="raised"><Text style={styles.eyebrow}>รายละเอียดงาน</Text><Text style={styles.title}>{detail.title}</Text><Text style={styles.muted}>{detail.workDate} · {detail.assigneePersonIds.map((id) => personName(ready.workers, id)).join(', ')}</Text></FieldCard><SectionHeader title="สถานะค่าแรง" />{detail.wageContexts.length ? <LedgerListCard>{detail.wageContexts.map((context) => <LedgerListRow key={`${context.sourceKind}:${context.sourceUnitId}`}><LedgerRowText title={context.sourceKind === 'contract' ? 'งานเหมา' : context.sourceKind === 'daily' ? 'ค่าแรงรายวัน' : 'ค่าแรงรายชั่วโมง'} detail={context.state === 'open_unpriced' ? 'รอสรุปยอด' : context.state === 'paid' ? 'จ่ายครบแล้ว' : context.state === 'partial' ? 'จ่ายบางส่วน' : 'ค้างจ่าย'} /><LedgerTrailing><Text style={styles.caption}>{context.remainingSatang === null ? '—' : baht(context.remainingSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่ผูกค่าแรงกับงานนี้" />}<LegacyReadContext ready={ready} /></View>; }
function LegacyReadContext({ ready }: { ready: Ready }) { const [legacy, setLegacy] = useState<Awaited<ReturnType<LaborV2Adapter['legacyRead']>> | null>(null); useEffect(() => { void ready.adapter.legacyRead().then(setLegacy); }, [ready.adapter]); if (!legacy?.jobs.length) return null; return <View style={styles.section}><SectionHeader title="ข้อมูลจากระบบเดิม" /><FieldCard><Text style={styles.caption}>{legacy.sourceLabel}</Text><Text style={styles.muted}>ข้อมูลนี้มีไว้ดูย้อนหลังเท่านั้น และไม่รวมกับยอดค่าแรงในสมุดงานปัจจุบัน</Text></FieldCard></View>; }
function WorkFilterSheet({ visible, value, workers, onChange, onClose, onApply }: { visible: boolean; value: LaborV2WorkListFilters; workers: LaborWorker[]; onChange: (value: LaborV2WorkListFilters) => void; onClose: () => void; onApply: () => void }) { const [personPicker, setPersonPicker] = useState(false); const [query, setQuery] = useState(''); const options = workers.filter((worker) => !worker.archivedAt).map((worker) => ({ id: worker.id, label: worker.displayName, meta: worker.specialty })); return <><Modal animationType="slide" presentationStyle="overFullScreen" transparent visible={visible} onRequestClose={onClose}><View style={styles.sheetBackdrop}><View style={styles.filterSheet}><View style={styles.rowHeader}><Text style={styles.title}>ตัวกรองงาน</Text><Pressable onPress={onClose}><Text style={styles.route}>ปิด</Text></Pressable></View><TextInput value={value.startDate ?? ''} onChangeText={(startDate) => onChange({ ...value, startDate: startDate || undefined })} placeholder="ตั้งแต่วันที่ YYYY-MM-DD" style={styles.input} /><TextInput value={value.endDate ?? ''} onChangeText={(endDate) => onChange({ ...value, endDate: endDate || undefined })} placeholder="ถึงวันที่ YYYY-MM-DD" style={styles.input} /><PickerField label="คนทำงาน" value={value.personId ? personName(workers, value.personId) : ''} placeholder="ทั้งหมด" onPress={() => setPersonPicker(true)} />{value.personId ? <Pressable onPress={() => onChange({ ...value, personId: undefined })}><Text style={styles.route}>ล้างคนที่เลือก</Text></Pressable> : null}<View style={styles.segment}>{(['daily', 'hourly', 'contract'] as const).map((kind) => <Pressable key={kind} onPress={() => onChange({ ...value, sourceKind: value.sourceKind === kind ? undefined : kind })} style={[styles.segmentItem, value.sourceKind === kind && styles.segmentActive]}><Text style={value.sourceKind === kind ? styles.activeText : styles.caption}>{kind === 'daily' ? 'รายวัน' : kind === 'hourly' ? 'รายชั่วโมง' : 'งานเหมา'}</Text></Pressable>)}</View><View style={styles.segment}>{(['unpaid', 'partial', 'paid', 'open_unpriced'] as const).map((state) => <Pressable key={state} onPress={() => onChange({ ...value, wageState: value.wageState === state ? undefined : state })} style={[styles.segmentItem, value.wageState === state && styles.segmentActive]}><Text style={value.wageState === state ? styles.activeText : styles.caption}>{state === 'unpaid' ? 'ค้าง' : state === 'partial' ? 'บางส่วน' : state === 'paid' ? 'จ่ายแล้ว' : 'รอสรุป'}</Text></Pressable>)}</View><PrimaryButton label="ใช้ตัวกรอง" onPress={onApply} /><PrimaryButton label="ล้างตัวกรอง" variant="secondary" onPress={() => onChange({})} /></View></View></Modal><SearchPickerSheet visible={personPicker} title="เลือกคนทำงาน" query={query} setQuery={setQuery} options={options} recentIds={[]} onPick={(personId) => { onChange({ ...value, personId }); setPersonPicker(false); }} onClose={() => setPersonPicker(false)} emptyLabel="ยังไม่มีคนทำงาน" /></>; }

function OpenContractCard({ contract, ready, refresh, notify }: { contract: LaborV2OpenContractBatch; ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void }) { const [progress, setProgress] = useState(''); const [total, setTotal] = useState(''); const [saving, setSaving] = useState(false); const members = contract.memberPersonIds.map((id) => personName(ready.workers, id)).join(', '); const save = async (kind: 'progress' | 'final') => { const amount = Number(total) * 100; if (kind === 'final' && (!Number.isSafeInteger(amount) || amount <= 0)) return notify('กรอกยอดเหมาสุดท้ายเป็นบาท'); setSaving(true); try { if (kind === 'progress') await ready.adapter.commands.progressContract(contract.id, { progressDate: ready.date, note: progress }); else await ready.adapter.commands.finalizeContract(contract.id, { finalizedAt: ready.date, finalization: { kind: 'lump_total', finalTotalSatang: amount } }); await refresh(); notify(kind === 'progress' ? 'บันทึกความคืบหน้างานเหมาแล้ว' : 'ปิดงานเหมาและสร้างก้อนรับเงินแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'บันทึกงานเหมาไม่สำเร็จ'); } finally { setSaving(false); } }; return <FieldCard><Text style={styles.title}>{contract.title}</Text><Text style={styles.caption}>เริ่ม {contract.startsOn} · {members}</Text><TextInput style={styles.input} value={progress} onChangeText={setProgress} placeholder="บันทึกความคืบหน้า (ไม่บังคับ)" /><PrimaryButton disabled={saving} label="บันทึกความคืบหน้า" variant="secondary" onPress={() => save('progress')} /><MoneyInput label="ยอดเหมาสุดท้าย (บาท)" value={total} onChange={setTotal} /><PrimaryButton disabled={saving} label="ปิดงานเหมาสร้างก้อนรับเงิน" onPress={() => save('final')} /></FieldCard>; }

function RecordScreen({ ready, refresh, notify, onPayment }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; onPayment: () => void }) {
  return <LaborRecordGroupEditor ready={ready} refresh={refresh} notify={notify} onPayment={onPayment} />;
  /* Retained only as pre-V2-editor source history; this branch is unreachable.
  const scenario = selectLaborWebProofScenario(); const su = 'labor-v2-preview-su'; const phuang = 'labor-v2-preview-phuang'; const [workDate, setWorkDate] = useState(scenario ? '2026-08-21' : ready.date); const [tasks, setTasks] = useState(() => scenario === 'daily-three-task' || scenario === 'open-contract' ? [{ id: 'proof-task-1', title: 'ตัดหญ้า', people: [su] }, { id: 'proof-task-2', title: 'ใส่ปุ๋ย', people: [su] }, { id: 'proof-task-3', title: 'พ่นยา', people: [su] }] : [{ id: 'new-task-1', title: '', people: [] as string[] }]); const [units, setUnits] = useState<Array<{ id: string; kind: Kind; personId: string | null; minutes: string; title: string; members: string[] }>>(() => scenario === 'open-contract' ? [{ id: 'proof-contract', kind: 'contract', personId: null, minutes: '60', title: 'กรอกถุงเพาะชำ', members: [su, phuang] }] : [{ id: 'proof-daily', kind: 'daily', personId: su, minutes: '60', title: '', members: [] }]); const [pick, setPick] = useState<'unit' | 'contract' | number | null>(null); const [unitPick, setUnitPick] = useState<string | null>(null); const [query, setQuery] = useState(''); const [saving, setSaving] = useState(false);
  const activePeople = ready.workers.filter((item) => !item.archivedAt); const options = activePeople.map((item) => ({ id: item.id, label: item.displayName, meta: item.specialty })); const setTask = (index: number, change: Partial<(typeof tasks)[number]>) => setTasks((items) => items.map((task, taskIndex) => taskIndex === index ? { ...task, ...change } : task)); const setUnit = (id: string, change: Partial<(typeof units)[number]>) => setUnits((items) => items.map((item) => item.id === id ? { ...item, ...change } : item));
  const save = async () => { const valid = tasks.filter((item) => item.title.trim() && item.people.length); if (!valid.length || !units.length) return notify('เพิ่ม task และหน่วยค่าตอบแทนก่อนบันทึก'); setSaving(true); try { const taskFacts = valid.map((item) => ({ id: item.id, title: item.title.trim(), assigneePersonIds: item.people })); const daily = units.filter((item) => item.kind === 'daily' && item.personId).map((item) => ({ personId: item.personId!, rateSatang: 35_000, quantityMilli: 1000 as const, taskIds: valid.filter((task) => task.people.includes(item.personId!)).map((task) => task.id) })); const hourly = units.filter((item) => item.kind === 'hourly' && item.personId).flatMap((item) => valid.filter((task) => task.people.includes(item.personId!)).map((task, index) => ({ id: `${item.id}-${index}`, taskId: task.id, personId: item.personId!, rateSatang: 12_000, durationMinutes: Number(item.minutes) || 60 }))); if (daily.some((item) => !item.taskIds.length) || !units.filter((item) => item.kind === 'contract').every((item) => item.title.trim() && item.members.length)) throw new Error('ตรวจคนของแต่ละหน่วยค่าตอบแทนให้ครบ'); await ready.adapter.commands.recordDay({ workDate, tasks: taskFacts, daily, hourly }); for (const unit of units.filter((item) => item.kind === 'contract')) await ready.adapter.commands.startContract({ title: unit.title.trim(), startsOn: workDate, memberPersonIds: unit.members, taskIds: valid.map((item) => item.id) }); await refresh(); notify('บันทึก task และหน่วยค่าตอบแทนแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'บันทึกงานไม่สำเร็จ'); } finally { setSaving(false); } };
  return <><DatePickerField label="วันที่ทำงาน" value={workDate} onChange={setWorkDate} />{scenario === 'daily-three-task' ? <FieldCard variant="raised"><Text style={styles.title}>3 task · พี่สุ · 1 หน่วยรายวัน</Text><Text style={styles.caption}>ตัดหญ้า, ใส่ปุ๋ย, พ่นยา รวมเป็นค่าตอบแทนรายวันครั้งเดียว</Text></FieldCard> : null}{scenario === 'open-contract' ? <FieldCard variant="raised"><Text style={styles.title}>งานเหมา · กรอกถุงเพาะชำ · 2 คน</Text><Text style={styles.caption}>เปิดชุดงานแล้ว · ยังไม่ต้องใส่ราคาและยังไม่มีเงินค้างจ่าย</Text></FieldCard> : null}{scenario ? <View style={styles.section}><SectionHeader title="Task ที่ทำ" /><LedgerListCard>{tasks.map((item) => <LedgerListRow key={item.id}><LedgerRowText title={item.title} detail={item.people.map((id) => personName(activePeople, id)).join(', ')} /><LedgerTrailing><Text style={styles.caption}>task</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard></View> : <TaskListEditor tasks={tasks} workers={activePeople} onAdd={() => setTasks((items) => [...items, { id: `new-task-${Date.now()}`, title: '', people: [] }])} onChange={setTask} onPick={(index) => setPick(index)} onRemove={(index) => setTasks((items) => items.length === 1 ? items : items.filter((_item, taskIndex) => taskIndex !== index))} />}<View style={styles.section}><SectionHeader title="หน่วยค่าตอบแทน" />{units.map((unit) => <FieldCard key={unit.id}><View style={styles.rowHeader}><Text style={styles.title}>{unit.kind === 'daily' ? 'รายวัน · รวมอัตโนมัติ' : unit.kind === 'hourly' ? 'รายชั่วโมง · คนและกะ' : 'งานเหมา · เปิดชุดงาน'}</Text><Pressable onPress={() => setUnits((items) => items.filter((item) => item.id !== unit.id))}><Text style={styles.remove}>ลบ</Text></Pressable></View>{unit.kind === 'contract' ? <><TextInput style={styles.input} value={unit.title} onChangeText={(title) => setUnit(unit.id, { title })} placeholder="ชื่อชุดงาน" /><PickerField label="สมาชิกชุดงาน" value={`${unit.members.length} คน`} placeholder="เลือกสมาชิก" onPress={() => { setUnitPick(unit.id); setPick('contract'); }} /><Text style={styles.caption}>ยังไม่ต้องใส่ราคา · เปิดไว้ก่อนได้</Text></> : <><PickerField label="คนทำงาน" value={personName(activePeople, unit.personId)} placeholder="เลือกคน" onPress={() => { setUnitPick(unit.id); setPick('unit'); }} />{unit.kind === 'hourly' ? <MoneyInput label="นาทีในกะ" value={unit.minutes} onChange={(minutes) => setUnit(unit.id, { minutes })} /> : <Text style={styles.caption}>หลาย task ของคนเดียวกันรวมเป็น 1 หน่วยรายวัน</Text>}</>}</FieldCard>)}</View><View style={styles.segment}>{(['daily', 'hourly', 'contract'] as Kind[]).map((kind) => <Pressable key={kind} onPress={() => setUnits((items) => [...items, { id: `unit-${Date.now()}-${kind}`, kind, personId: null, minutes: '60', title: '', members: [] }])} style={styles.segmentItem}><Text style={styles.caption}>+ {kind === 'daily' ? 'รายวัน' : kind === 'hourly' ? 'รายชั่วโมง' : 'งานเหมา'}</Text></Pressable>)}</View><FormFeedback kind="notice">เพิ่มได้หลายหน่วยในวันเดียว: รายวันของคนหนึ่ง และงานเหมาแบบยังไม่รู้ราคาอยู่ร่วมกันได้</FormFeedback><PrimaryButton disabled={saving} label={saving ? 'กำลังบันทึก…' : 'บันทึกงาน'} onPress={save} /><PrimaryButton label="ไปจ่ายจากก้อนค่าตอบแทน" variant="secondary" onPress={onPayment} />
  <MultiSearchPickerSheet visible={typeof pick === 'number'} title="คนทำงานใน task" query={query} setQuery={setQuery} options={options} selectedIds={typeof pick === 'number' ? tasks[pick]?.people ?? [] : []} onToggle={(id) => { if (typeof pick !== 'number') return; const selected = tasks[pick]?.people ?? []; setTask(pick, { people: selected.includes(id) ? selected.filter((item) => item !== id) : [...selected, id] }); }} onClose={() => setPick(null)} emptyLabel="ยังไม่มีคนทำงาน" />
  <SearchPickerSheet visible={pick === 'unit'} title="เลือกคนของหน่วยค่าตอบแทน" query={query} setQuery={setQuery} options={options} recentIds={[]} onPick={(id) => { if (unitPick) setUnit(unitPick, { personId: id }); setPick(null); }} onClose={() => setPick(null)} emptyLabel="ยังไม่มีคนทำงาน" />
  <MultiSearchPickerSheet visible={pick === 'contract'} title="สมาชิกชุดงานเหมา" query={query} setQuery={setQuery} options={options} selectedIds={units.find((item) => item.id === (unitPick ?? ''))?.members ?? []} onToggle={(id) => { if (!unitPick) return; const members = units.find((item) => item.id === unitPick)?.members ?? []; setUnit(unitPick, { members: members.includes(id) ? members.filter((item) => item !== id) : [...members, id] }); }} onClose={() => setPick(null)} emptyLabel="ยังไม่มีคนทำงาน" /></>;
  */
}

function PaymentScreen({ ready, refresh, notify, preferredPersonId }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; preferredPersonId?: string | null }) {
  const proofPayment = selectLaborWebProofScenario() === 'payment-selection'; const [id, setId] = useState<string | null>(() => proofPayment ? ready.model.obligations.find((item) => item.remainingSatang > 0)?.id ?? null : null); const [picker, setPicker] = useState(proofPayment); const [advancePicker, setAdvancePicker] = useState(false); const [query, setQuery] = useState(''); const [bonus, setBonus] = useState('0'); const [wage, setWage] = useState(''); const [advance, setAdvance] = useState<string | null>(null); const [recovery, setRecovery] = useState('0'); const [issueAmount, setIssueAmount] = useState(''); const [issueNote, setIssueNote] = useState(''); const [confirm, setConfirm] = useState(false); const [saving, setSaving] = useState(false); const outstanding = ready.model.obligations.filter((item) => item.remainingSatang > 0); const selected = outstanding.find((item) => item.id === id) ?? null; const options = outstanding.map((item) => ({ id: item.id, label: `${item.sourceKind === 'contract' ? 'ชุดงานเหมา' : item.sourceKind === 'daily' ? 'รายวัน' : 'รายชั่วโมง'} · ${baht(item.remainingSatang)}`, meta: item.recipientKind === 'group' ? 'ก้อนเดียวของชุดงาน' : personName(ready.workers, item.personId) })); const advances = selected?.recipientKind === 'person' ? ready.advances.filter((item) => item.personId === selected.personId && item.remainingSatang > 0) : []; const advanceOptions = advances.map((item) => ({ id: item.id, label: `${baht(item.remainingSatang)} · ${item.advanceDate}`, meta: item.note || 'เงินเบิกคงเหลือ' }));
  useEffect(() => { if (!preferredPersonId) return; const next = outstanding.find((item) => item.recipientKind === 'person' && item.personId === preferredPersonId); if (next) { setId(next.id); setWage(String(next.remainingSatang / 100)); setPicker(false); } }, [preferredPersonId, ready.model.obligations]);
  const post = async () => { if (!selected) return; setSaving(true); try { const wageSatang = Math.round(Number(wage || selected.remainingSatang / 100) * 100); const recoverySatang = Number(recovery) * 100; await ready.adapter.commands.postPayment({ paymentDate: ready.date, method: 'cash', settlements: [{ obligationId: selected.id, wageSatang, bonusSatang: Number(bonus) * 100, advanceRecoveries: recoverySatang > 0 && advance ? [{ advanceId: advance, amountSatang: recoverySatang }] : [] }] }); await refresh(); notify('บันทึกรายการการเงินแล้ว'); setId(null); } catch (error) { notify(error instanceof Error ? error.message : 'จ่ายเงินไม่สำเร็จ'); } finally { setConfirm(false); setSaving(false); } }; const issue = async () => { if (!selected?.personId) return; const amountSatang = Math.round(Number(issueAmount) * 100); if (!amountSatang) return notify('กรอกเงินเบิกเป็นบาท'); try { await ready.adapter.personFinance.issueAdvance({ personId: selected.personId, advanceDate: ready.date, amountSatang, method: 'cash', note: issueNote }); await refresh(); setIssueAmount(''); setIssueNote(''); notify('ออกเงินเบิกให้คนทำงานแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'ออกเงินเบิกไม่สำเร็จ'); } };
  return <><FieldCard variant="raised"><Text style={styles.title}>จ่ายเงินจากก้อนค่าตอบแทน</Text><Text style={styles.muted}>หน้านี้ไม่แก้ task และไม่สร้างหนี้ใหม่ งานเหมาเป็นก้อนเดียว</Text></FieldCard><PickerField label="ก้อนค่าตอบแทนค้างจ่าย" value={options.find((item) => item.id === id)?.label} placeholder="เลือกก้อนที่จะจ่าย" onPress={() => setPicker(true)} />{selected ? <><FieldCard><Text style={styles.eyebrow}>{selected.recipientKind === 'group' ? 'ชุดรับเงิน' : 'คนทำงาน'}</Text><Text style={styles.title}>{baht(selected.remainingSatang)}</Text><Text style={styles.caption}>โบนัสไม่เพิ่มสิทธิ์หักเงินเบิก และงานเหมาไม่หักเงินเบิกของสมาชิก</Text></FieldCard><MoneyInput label="จ่ายค่าแรง (บาท)" value={wage} onChange={setWage} /><MoneyInput label="โบนัส (บาท)" value={bonus} onChange={setBonus} />{selected.recipientKind === 'person' ? <><MoneyInput label="หักเงินเบิก (บาท)" value={recovery} onChange={setRecovery} /><PickerField label="เลือกเงินเบิกของคนนี้" value={advanceOptions.find((item) => item.id === advance)?.label} placeholder="เลือกเงินเบิก (ถ้ามี)" onPress={() => setAdvancePicker(true)} /><FieldCard><Text style={styles.eyebrow}>ออกเงินเบิกให้ {personName(ready.workers, selected.personId)}</Text><MoneyInput label="จำนวนเงินเบิก (บาท)" value={issueAmount} onChange={setIssueAmount} /><TextInput style={styles.input} value={issueNote} onChangeText={setIssueNote} placeholder="หมายเหตุ (ไม่บังคับ)" /><PrimaryButton label="บันทึกเงินเบิก" variant="secondary" onPress={issue} /></FieldCard></> : null}<PrimaryButton disabled={saving} label="ตรวจแล้ว ยืนยันจ่ายเงิน" onPress={() => setConfirm(true)} /></> : <Empty label="เลือกก้อนค่าตอบแทนก่อน" />}<PayablePickerSheet visible={picker} query={query} setQuery={setQuery} options={options} onPick={(value) => { setId(value); setWage(String((outstanding.find((item) => item.id === value)?.remainingSatang ?? 0) / 100)); setAdvance(null); setPicker(false); }} onClose={() => setPicker(false)} /><SearchPickerSheet visible={advancePicker} title="เลือกเงินเบิกของคนนี้" query={query} setQuery={setQuery} options={advanceOptions} recentIds={[]} onPick={(value) => { setAdvance(value); setAdvancePicker(false); }} onClose={() => setAdvancePicker(false)} emptyLabel="ไม่มีเงินเบิกคงเหลือ" /><ConfirmActionSheet visible={confirm} title="ยืนยันการจ่ายเงิน" detail={selected ? `จ่าย ${wage || baht(selected.remainingSatang)} จากก้อนที่เลือก` : ''} cancelLabel="กลับไปตรวจ" confirmLabel="ยืนยันจ่าย" onCancel={() => setConfirm(false)} onConfirm={post} /></>;
}

function PeopleScreen({ ready, refresh, notify, onPayment }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; onPayment: (personId: string) => void }) {
  const [adding, setAdding] = useState(false); const [name, setName] = useState(''); const [specialty, setSpecialty] = useState(''); const [query, setQuery] = useState(''); const [showArchived, setShowArchived] = useState(false); const [personId, setPersonId] = useState<string | null>(null);
  const create = async () => { if (!name.trim()) return notify('กรอกชื่อคนทำงาน'); try { await ready.adapter.workers.create({ displayName: name.trim(), specialty: specialty.trim() }); await refresh(); setName(''); setSpecialty(''); setAdding(false); notify('เพิ่มคนทำงานแล้ว'); } catch { notify('เพิ่มคนทำงานไม่สำเร็จ'); } };
  if (personId) return <PersonDetailScreen ready={ready} refresh={refresh} notify={notify} personId={personId} onBack={() => setPersonId(null)} onPayment={onPayment} />;
  const matches = (worker: LaborWorker) => `${worker.displayName} ${worker.specialty} ${worker.phone}`.toLowerCase().includes(query.trim().toLowerCase()); const active = ready.workers.filter((item) => !item.archivedAt && matches(item)); const archived = ready.workers.filter((item) => item.archivedAt && matches(item));
  return <><FieldCard variant="raised"><Text style={styles.title}>คนทำงาน</Text><Text style={styles.muted}>รายชื่อที่เก็บไว้ใช้เลือกงานใหม่ได้เฉพาะคนที่ใช้งานอยู่</Text></FieldCard><TextInput style={styles.input} value={query} onChangeText={setQuery} placeholder="ค้นหาชื่อ งานที่ถนัด หรือเบอร์โทร" /><SectionHeader title={`กำลังใช้งาน (${active.length})`} /><LedgerListCard>{active.map((item) => <Pressable key={item.id} onPress={() => setPersonId(item.id)}><LedgerListRow><LedgerRowText title={item.displayName} detail={item.specialty || 'ยังไม่ได้ระบุงานที่ถนัด'} /><LedgerTrailing><Text style={styles.route}>ดูข้อมูล</Text></LedgerTrailing></LedgerListRow></Pressable>)}</LedgerListCard>{!active.length ? <Empty label="ไม่พบคนทำงาน" /> : null}<Pressable onPress={() => setShowArchived((value) => !value)}><Text style={styles.route}>{showArchived ? 'ซ่อนรายชื่อที่เก็บไว้' : `ดูรายชื่อที่เก็บไว้ (${archived.length})`}</Text></Pressable>{showArchived ? <><SectionHeader title="รายชื่อที่เก็บไว้" /><LedgerListCard>{archived.map((item) => <Pressable key={item.id} onPress={() => setPersonId(item.id)}><LedgerListRow><LedgerRowText title={item.displayName} detail={item.specialty || 'ประวัติคนทำงาน'} /><LedgerTrailing><Text style={styles.caption}>เก็บไว้</Text></LedgerTrailing></LedgerListRow></Pressable>)}</LedgerListCard></> : null}<PrimaryButton label={adding ? 'ยกเลิก' : '+ เพิ่มคนทำงาน'} onPress={() => setAdding((value) => !value)} />{adding ? <FieldCard><TextInput style={styles.input} value={name} onChangeText={setName} placeholder="ชื่อคนทำงาน" /><TextInput style={styles.input} value={specialty} onChangeText={setSpecialty} placeholder="งานที่ถนัด (ไม่บังคับ)" /><PrimaryButton label="บันทึกคนทำงาน" onPress={create} /></FieldCard> : null}</>;
}

function PersonDetailScreen({ ready, refresh, notify, personId, onBack, onPayment }: { ready: Ready; refresh: () => Promise<void>; notify: (text: string) => void; personId: string; onBack: () => void; onPayment: (personId: string) => void }) {
  const person = ready.workers.find((item) => item.id === personId); const [detail, setDetail] = useState<LaborV2PersonDetail | null>(null); const [editing, setEditing] = useState(false); const [archiveConfirm, setArchiveConfirm] = useState(false); const [displayName, setDisplayName] = useState(person?.displayName ?? ''); const [specialty, setSpecialty] = useState(person?.specialty ?? ''); const [phone, setPhone] = useState(person?.phone ?? ''); const [note, setNote] = useState(person?.note ?? ''); const [reason, setReason] = useState(''); const [saving, setSaving] = useState(false);
  useEffect(() => { void ready.adapter.getPersonDetail(personId).then(setDetail).catch(() => notify('เปิดข้อมูลคนทำงานไม่สำเร็จ')); }, [ready.adapter, personId]);
  if (!person) return <Empty label="ไม่พบคนทำงาน" />;
  const workDates = [...new Set(detail?.tasks.map((task) => task.workDate) ?? [])].sort().reverse(); const unpaid = detail?.obligations.filter((item) => item.remainingSatang > 0).reduce((sum, item) => sum + item.remainingSatang, 0) ?? 0; const advanceRemaining = detail?.advances.reduce((sum, item) => sum + item.remainingSatang, 0) ?? 0;
  const save = async () => { if (!reason.trim()) return notify('บอกเหตุผลที่แก้ไขก่อนบันทึก'); setSaving(true); try { await ready.adapter.workers.update(personId, { displayName, specialty, phone, note, reason }); await refresh(); setReason(''); setEditing(false); notify('บันทึกการแก้ไขพร้อมประวัติแล้ว'); } catch (error) { notify(error instanceof Error ? error.message : 'แก้ไขข้อมูลไม่สำเร็จ'); } finally { setSaving(false); } };
  const archive = async () => { if (!reason.trim()) return notify('บอกเหตุผลที่เก็บรายชื่อก่อน'); setSaving(true); try { await ready.adapter.workers.archive(personId, reason); await refresh(); notify('เก็บรายชื่อไว้แล้ว ประวัติเดิมยังดูได้'); onBack(); } catch (error) { notify(error instanceof Error ? error.message : 'เก็บรายชื่อไม่สำเร็จ'); } finally { setSaving(false); setArchiveConfirm(false); } };
  return <View style={styles.listScreen}><Pressable onPress={onBack}><Text style={styles.route}>‹ กลับไปรายชื่อ</Text></Pressable><FieldCard variant="raised"><Text style={styles.eyebrow}>{person.archivedAt ? 'รายชื่อที่เก็บไว้' : 'คนทำงาน'}</Text><Text style={styles.title}>{person.displayName}</Text><Text style={styles.muted}>{person.specialty || 'ยังไม่ได้ระบุงานที่ถนัด'}{person.phone ? ` · ${person.phone}` : ''}</Text>{person.note ? <Text style={styles.caption}>{person.note}</Text> : null}</FieldCard><Summary items={[["ค่าแรงค้างจ่าย", unpaid, false], ["เงินเบิกคงเหลือ", advanceRemaining, false], ["งานที่บันทึก", detail?.tasks.length ?? 0, true]]} />{!person.archivedAt ? <><PrimaryButton label="ไปจ่ายเงินให้คนนี้" onPress={() => onPayment(personId)} /><PrimaryButton label={editing ? 'ยกเลิกแก้ไข' : 'แก้ไขข้อมูล'} variant="secondary" onPress={() => { setEditing((value) => !value); setReason(''); }} /></> : <FieldCard><Text style={styles.caption}>รายชื่อนี้เก็บไว้แล้ว จึงเลือกบันทึกงานใหม่ไม่ได้ แต่ประวัติยังอยู่ครบ</Text></FieldCard>}{editing ? <FieldCard><SectionHeader title="แก้ไขข้อมูลคนทำงาน" /><TextInput style={styles.input} value={displayName} onChangeText={setDisplayName} placeholder="ชื่อคนทำงาน" /><TextInput style={styles.input} value={specialty} onChangeText={setSpecialty} placeholder="งานที่ถนัด" /><TextInput style={styles.input} value={phone} onChangeText={setPhone} placeholder="เบอร์โทร" keyboardType="phone-pad" /><TextInput style={styles.input} value={note} onChangeText={setNote} placeholder="หมายเหตุ" /><TextInput style={styles.input} value={reason} onChangeText={setReason} placeholder="เหตุผลที่แก้ไข (จำเป็น)" /><PrimaryButton disabled={saving} label="บันทึกการแก้ไข" onPress={save} /></FieldCard> : null}<SectionHeader title="ปฏิทินและงานที่ทำ" />{workDates.length ? <LedgerListCard>{workDates.map((workDate) => <LedgerListRow key={workDate}><LedgerRowText title={workDate} detail={(detail?.tasks.filter((task) => task.workDate === workDate).map((task) => task.title) ?? []).join(', ')} /><LedgerTrailing><Text style={styles.caption}>{detail?.tasks.filter((task) => task.workDate === workDate).length} งาน</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่มีงาน V2 ของคนนี้" />}<SectionHeader title="การจ่ายเงินของคนนี้" />{detail?.payments.length ? <LedgerListCard>{detail.payments.map((payment) => <LedgerListRow key={payment.id}><LedgerRowText title={`จ่ายวันที่ ${payment.paymentDate}`} detail="ประวัติการจ่ายค่าแรงของคนนี้" /><LedgerTrailing><Text style={styles.caption}>{baht(payment.cashPaidSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่มีประวัติการจ่ายเงิน V2" />}<SectionHeader title="เงินเบิก" />{detail?.advances.length ? <LedgerListCard>{detail.advances.map((advance) => <LedgerListRow key={advance.id}><LedgerRowText title={advance.advanceDate} detail={advance.note || 'เงินเบิก'} /><LedgerTrailing><Text style={styles.caption}>เหลือ {baht(advance.remainingSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ไม่มีเงินเบิก" />}<LegacyReadContext ready={ready} />{!person.archivedAt ? <><TextInput style={styles.input} value={reason} onChangeText={setReason} placeholder="เหตุผลที่เก็บรายชื่อ (จำเป็น)" /><PrimaryButton label="เก็บรายชื่อคนนี้" variant="secondary" onPress={() => setArchiveConfirm(true)} /><ConfirmActionSheet visible={archiveConfirm} title="เก็บรายชื่อคนทำงาน" detail="จะยังเก็บประวัติงานและการเงินไว้ดูได้ แต่ใช้เลือกงานใหม่ไม่ได้" cancelLabel="กลับไปตรวจ" confirmLabel="ยืนยันเก็บรายชื่อ" onCancel={() => setArchiveConfirm(false)} onConfirm={archive} /></> : null}</View>;
}

function TaskListEditor({ tasks, workers, onAdd, onChange, onPick, onRemove }: { tasks: Array<{ id: string; title: string; people: string[] }>; workers: LaborWorker[]; onAdd: () => void; onChange: (index: number, value: Partial<{ id: string; title: string; people: string[] }>) => void; onPick: (index: number) => void; onRemove: (index: number) => void }) { return <View style={styles.section}><SectionHeader title="Task ที่ทำ" />{tasks.map((item, index) => <FieldCard key={item.id}><TextInput style={styles.input} value={item.title} onChangeText={(title) => onChange(index, { title })} placeholder={`งานที่ ${index + 1}`} /><PickerField label="คนทำงาน" value={item.people.map((id) => personName(workers, id)).join(', ')} placeholder="เลือกคนใน task" onPress={() => onPick(index)} /><Pressable onPress={() => onRemove(index)}><Text style={styles.remove}>ลบ task นี้</Text></Pressable></FieldCard>)}<PrimaryButton label="+ เพิ่ม task" variant="secondary" onPress={onAdd} /></View>; }
function CompensationUnitCard({ kind, onKind, unitName, minutes, contractTitle, contractCount, onUnit, onMinutes, onContractTitle, onContract }: { kind: Kind; onKind: (value: Kind) => void; unitName: string; minutes: string; contractTitle: string; contractCount: number; onUnit: () => void; onMinutes: (value: string) => void; onContractTitle: (value: string) => void; onContract: () => void }) { return <View style={styles.section}><SectionHeader title="หน่วยค่าตอบแทน" /><View style={styles.segment}>{(['daily', 'hourly', 'contract'] as Kind[]).map((item) => <Pressable key={item} onPress={() => onKind(item)} style={[styles.segmentItem, kind === item && styles.segmentActive]}><Text style={kind === item ? styles.activeText : styles.caption}>{item === 'daily' ? 'รายวัน' : item === 'hourly' ? 'รายชั่วโมง' : 'งานเหมา'}</Text></Pressable>)}</View><FieldCard>{kind === 'daily' ? <><Text style={styles.title}>รายวัน · รวมอัตโนมัติ</Text><PickerField label="คนทำงาน" value={unitName} placeholder="เลือกคน" onPress={onUnit} /><Text style={styles.caption}>หนึ่งคนหนึ่งวันได้ไม่เกินเต็มวัน</Text></> : null}{kind === 'hourly' ? <><Text style={styles.title}>รายชั่วโมง · คนและกะ</Text><PickerField label="คนทำงาน" value={unitName} placeholder="เลือกคน" onPress={onUnit} /><MoneyInput label="นาทีในกะ" value={minutes} onChange={onMinutes} /><Text style={styles.caption}>อัตราเดียวกันรวมกันเฉพาะในคำสั่งนี้</Text></> : null}{kind === 'contract' ? <><Text style={styles.title}>งานเหมา · เปิดชุดงานก่อนได้</Text><TextInput style={styles.input} value={contractTitle} onChangeText={onContractTitle} placeholder="ชื่อชุดงาน" /><PickerField label="สมาชิกชุดงาน" value={`${contractCount} คน`} placeholder="เลือกสมาชิก" onPress={onContract} /><Text style={styles.caption}>ไม่ต้องใส่ราคา/จำนวนตอนเปิดงาน</Text></> : null}</FieldCard></View>; }
function PayablePickerSheet({ visible, query, setQuery, options, onPick, onClose }: { visible: boolean; query: string; setQuery: (value: string) => void; options: Array<{ id: string; label: string; meta: string }>; onPick: (id: string) => void; onClose: () => void }) { return <SearchPickerSheet visible={visible} title="เลือกก้อนค่าตอบแทน" query={query} setQuery={setQuery} options={options} recentIds={[]} onPick={onPick} onClose={onClose} emptyLabel="ไม่มีรายการค้างจ่าย" />; }
function TaskList({ tasks, workers }: { tasks: LaborV2ReadModel['tasks']; workers: LaborWorker[] }) { return tasks.length ? <LedgerListCard>{tasks.map((item) => <LedgerListRow key={item.id}><LedgerRowText title={item.title} detail={item.assigneePersonIds.map((id) => personName(workers, id)).join(', ')} /><LedgerTrailing><Text style={styles.caption}>งาน</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ยังไม่มีงาน" />; }
function ObligationList({ obligations, workers }: { obligations: LaborV2ReadModel['obligations']; workers: LaborWorker[] }) { return obligations.length ? <LedgerListCard>{obligations.map((item) => <LedgerListRow key={item.id}><LedgerRowText title={item.sourceKind === 'contract' ? 'ชุดงานเหมา' : item.sourceKind === 'daily' ? 'รายวัน' : 'รายชั่วโมง'} detail={item.recipientKind === 'group' ? 'ก้อนเดียวของชุดงาน' : personName(workers, item.personId)} /><LedgerTrailing><Text style={styles.caption}>{baht(item.remainingSatang)}</Text></LedgerTrailing></LedgerListRow>)}</LedgerListCard> : <Empty label="ไม่มีค่าตอบแทนค้างจ่าย" />; }
function Summary({ items }: { items: Array<[string, number, boolean]> }) { return <View style={styles.summary}>{items.map(([label, value, count]) => <View key={label} style={styles.summaryItem}><Text style={styles.caption}>{label}</Text><Text style={styles.summaryValue}>{count ? value : baht(value)}</Text></View>)}</View>; }
function MoneyInput({ label, value, onChange }: { label: string; value: string; onChange: (value: string) => void }) { return <View style={styles.field}><Text style={styles.label}>{label}</Text><TextInput style={styles.input} keyboardType="number-pad" value={value} onChangeText={onChange} /></View>; }
function Empty({ label }: { label: string }) { return <FieldCard><Text style={styles.muted}>{label}</Text></FieldCard>; }
